def insert_for_lang(s, lang, items):
    # insert before metadata near the end of the language map, skipping existing keys
    existing=[]
    for k in items:
        if f"'{k}':" in s[s.index(f"  '{lang}': {{"):]:
            # might find in later maps too, so extract block
            pass
    start=s.index(f"  '{lang}': {{")
    i=s.index('{', start); depth=0; end=None
    for j in range(i,len(s)):
        if s[j]=='{': depth+=1
        elif s[j]=='}':
            depth-=1
            if depth==0:
                end=j; break
    block=s[i:end]
    add=''
    for k,v in items.items():
        if f"'{k}':" in block: continue
        v=v.replace('\\','\\\\').replace("'","\\'")
        add += f"    '{k}': '{v}',\n"
    marker="    'metadata':"
    pos=s.index(marker, start)
    return s[:pos]+add+s[pos:]

for lang in ['fa','en','zh']:
    s=insert_for_lang(s, lang, extra[lang])
p.write_text(s)
